cat > styles.css <<'"'EOF'
:root {
  color-scheme: light;
  --primary: #086b64;
  --paper: #f7f5ef;
  --ink: #182d2a;
  --muted: #4d605b;
  --line: #c7d0c7;
  --surface: #edf0e8;
  --field: #fdfcf8;
  --radius: 12px;
  font-family: Georgia, 'Times New Roman', serif;
  color: var(--ink);
  background: var(--paper);
}
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; text-underline-offset: 5px; }
a:hover { color: var(--primary); }
button, input { font: inherit; }
button, a, input { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 3px solid var(--primary); outline-offset: 5px; }
.wrap { max-width: 1280px; margin-inline: auto; padding-inline: 64px; }
.skip-link { position: absolute; top: 12px; left: 12px; transform: translateY(-160%); background: var(--paper); padding: 12px; z-index: 1; }
.skip-link:focus { transform: none; }
.site-header { min-height: 80px; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--line); }
.wordmark { font-size: 25px; line-height: .95; text-decoration: none; letter-spacing: -.8px; }
.wordmark span { display: block; font-size: 15px; margin-top: 5px; letter-spacing: 1.3px; }
nav { display: flex; gap: 32px; align-items: center; }
nav a { font-size: 15px; text-decoration: none; padding-block: 13px; }
nav a:hover { text-decoration: underline; }
.membership-layout { display: grid; grid-template-columns: 1.25fr 1fr; gap: 74px; align-items: start; padding-block: 66px 58px; }
.introduction { padding-block: 17px; }
.eyebrow { font-size: 13px; letter-spacing: 1.7px; text-transform: uppercase; color: var(--primary); margin: 0 0 28px; }
h1 { font-size: clamp(56px, 5.7vw, 76px); font-weight: 400; line-height: 1.04; letter-spacing: -3.5px; max-width: 540px; margin: 0 0 27px; }
.intro-copy { font-size: 22px; line-height: 1.5; max-width: 350px; color: var(--muted); margin: 0 0 36px; }
.text-link { color: var(--primary); font-size: 17px; display: inline-flex; gap: 20px; align-items: center; min-height: 44px; }
.text-link span { font-size: 24px; }
.membership-panel { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 30px 32px 24px; }
h2 { font-weight: 400; }
.plan-heading h2 { font-size: 24px; letter-spacing: -.4px; margin: 0 0 16px; }
#price { margin: 0; color: var(--primary); }
.price-value { font-size: 60px; line-height: 1.1; letter-spacing: -3px; }
.price-period { font-size: 20px; }
.benefit { margin: 22px 0 26px; padding-bottom: 24px; border-bottom: 1px solid var(--line); font-size: 18px; line-height: 1.5; }
label { display: block; font-size: 16px; margin-bottom: 10px; }
input { width: 100%; min-height: 50px; border: 1px solid #768c83; border-radius: var(--radius); padding: 12px 14px; background: var(--field); color: var(--ink); font-size: 17px; }
input::placeholder { color: var(--muted); opacity: 1; }
.small, .pricing-note { font-size: 13px; color: var(--muted); line-height: 1.5; }
.small { margin: 10px 0 20px; }
button { border: 1px solid var(--primary); border-radius: var(--radius); padding: 15px 18px; width: 100%; min-height: 54px; display: flex; align-items: center; justify-content: space-between; gap: 12px; background: var(--primary); color: #f7f5ef; cursor: pointer; font-size: 17px; }
button:hover { background: #075a55; }
button:active { transform: translateY(1px); }
button:disabled { opacity: .65; cursor: default; }
#form-message { font-size: 15px; line-height: 1.5; margin: 0; color: var(--primary); }
#form-message:not(:empty) { margin-top: 16px; }
.pricing-note { margin: 18px 0 0; }
.museum-facts { border-top: 1px solid var(--line); padding: 30px 0 38px; }
.museum-facts h2 { margin: 0 0 25px; font-size: 25px; }
.facts-grid { margin: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.facts-grid > div { display: flex; flex-direction: column-reverse; gap: 9px; }
.facts-grid > div + div { border-left: 1px solid var(--line); padding-left: 36px; }
dt { font-size: 15px; color: var(--muted); }
dd { margin: 0; color: var(--primary); font-size: 44px; letter-spacing: -1.5px; line-height: 1.1; }
.site-footer { display: flex; align-items: center; justify-content: space-between; min-height: 78px; border-top: 1px solid var(--line); color: var(--muted); font-size: 14px; }
.site-footer p { margin: 0; }
.document { max-width: 800px; padding-block: 64px; min-height: 70vh; }
.document h1 { font-size: 54px; }
.document p { font-size: 20px; line-height: 1.6; }
@media (max-width: 1023px) {
  .wrap { padding-inline: 32px; }
  .membership-layout { gap: 36px; }
  h1 { font-size: 59px; }
  .membership-panel { padding: 26px; }
}
@media (max-width: 767px) {
  .wrap { padding-inline: 24px; }
  .site-header { min-height: 84px; }
  .wordmark { font-size: 22px; }
  .wordmark span { font-size: 13px; }
  nav { gap: 18px; }
  nav a { font-size: 13px; }
  .membership-layout { grid-template-columns: 1fr; gap: 35px; padding-block: 34px 38px; }
  .introduction { padding: 0; }
  .eyebrow { font-size: 11px; margin-bottom: 20px; }
  h1 { font-size: 58px; line-height: 1.04; letter-spacing: -2.7px; margin-bottom: 20px; }
  .intro-copy { font-size: 20px; margin-bottom: 17px; }
  .text-link { font-size: 16px; }
  .membership-panel { padding: 25px 23px; }
  .plan-heading h2 { font-size: 23px; }
  .price-value { font-size: 54px; }
  .benefit { margin-block: 18px 22px; padding-bottom: 21px; }
  .museum-facts { padding-block: 28px 34px; }
  .museum-facts h2 { font-size: 24px; }
  .facts-grid { grid-template-columns: 1fr; gap: 25px; }
  .facts-grid > div { flex-direction: row-reverse; align-items: baseline; justify-content: space-between; }
  .facts-grid > div + div { border: 0; padding: 0; }
  dd { font-size: 39px; }
  .site-footer { align-items: flex-start; flex-direction: column; gap: 5px; padding-block: 22px; }
  .document { padding-block: 40px; }
  .document h1 { font-size: 44px; }
}
@media (prefers-color-scheme: dark) {
  :root { color-scheme: dark; --paper: #182d2a; --ink: #f7f5ef; --primary: #91d4c7; --muted: #c1cec5; --line: #516760; --surface: #223a35; --field: #182d2a; }
  button { background: #086b64; border-color: #91d4c7; }
  button:hover { background: #075a55; }
}
EOF
